// Parse the incoming MQTT message
let regulated_data;
try {
  regulated_data = JSON.parse(msg.payload);
} catch (e) {
  node.error('Failed to parse JSON: ' + e.message, msg);
  return;
}

// Check if there are objects in the regulated data
if (!regulated_data || !regulated_data.objects || regulated_data.objects.length === 0) {
  node.warn('No objects found in regulated data');
  return;
}

// Find the first person object
let person_object = null;
for (let obj of regulated_data.objects) {
  if (obj.type === 'person' || obj.category === 'person' || obj.object_type === 'person' || obj.class === 'person') {
    person_object = obj;
    break;
  }
}

if (!person_object) {
  node.warn('No person object found in regulated data');
  return;
}

// Extract translation (position)
let translation = person_object.translation;
if (!translation || translation.length < 2) {
  node.error('Invalid translation data in person object', msg);
  return;
}

const x = translation[0];
const y = translation[1];
const z = translation.length > 2 ? translation[2] : 0.0;

// Create nav2 goal pose message
const nav2_goal = {
  header: {
    frame_id: 'map'
  },
  pose: {
    position: {
      x: x,
      y: y,
      z: z
    },
    orientation: {
      x: 0.0,
      y: 0.0,
      z: 0.0,
      w: 1.0
    }
  }
};

node.status({
  fill: 'green',
  shape: 'dot',
  text: `Person at (${x.toFixed(2)}, ${y.toFixed(2)}, ${z.toFixed(2)})`
});

// Send the goal pose to nav2/goal_pose topic
msg.payload = JSON.stringify(nav2_goal);
msg.topic = 'nav2/goal_pose';
return msg;
